CREATE OR REPLACE FUNCTION public.finance_legacy_readonly() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'السجل المالي التاريخي للقراءة فقط؛ استخدم العقود والأقساط والإيصالات' USING ERRCODE='42501'; END $$;
REVOKE ALL ON FUNCTION public.finance_legacy_readonly() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['invoices','unit_collections'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('public.'||t)::regclass AND tgname='finance_legacy_readonly') THEN EXECUTE format('CREATE TRIGGER finance_legacy_readonly BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.finance_legacy_readonly()',t); END IF; EXECUTE format('REVOKE INSERT,UPDATE,DELETE ON public.%I FROM authenticated,anon,service_role',t); EXECUTE format('COMMENT ON TABLE public.%I IS %L',t,'DEPRECATED: immutable historical financial source; new cash records use receipts and obligations use installments.'); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.reverse_collection(_collection_id uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid;BEGIN PERFORM public.finance_assert_writer();SELECT receipt_id INTO r FROM public.receipt_legacy_sources WHERE source_table='unit_collections' AND source_id=_collection_id AND resolution='distinct';IF r IS NULL THEN RAISE EXCEPTION 'راجع مصدر التحصيل وتكراره قبل تسجيل العكس في الإيصالات';END IF;RETURN public.reverse_receipt(r,_reason);END $$;
CREATE OR REPLACE FUNCTION public.reverse_payment(_invoice_id uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid;BEGIN PERFORM public.finance_assert_writer();SELECT receipt_id INTO r FROM public.receipt_legacy_sources WHERE source_table='invoices' AND source_id=_invoice_id AND resolution='distinct';IF r IS NULL THEN RAISE EXCEPTION 'راجع مصدر الفاتورة وتكراره قبل تسجيل العكس في الإيصالات';END IF;RETURN public.reverse_receipt(r,_reason);END $$;
-- Preserve each compatibility function's exact signature and defaults while rejecting balance edits.
DO $$ DECLARE f record;d text; BEGIN FOR f IN SELECT p.oid,p.proname FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN('adjust_payment','set_booking_paid_amount','set_tenant_account_paid_amount') LOOP SELECT pg_get_functiondef(f.oid) INTO d;d:=regexp_replace(d,'AS \$function\$.*\$function\$','AS $function$ BEGIN RAISE EXCEPTION ''المبالغ التاريخية للقراءة؛ سجل قيدًا عكسيًا أو إيصالًا جديدًا''; END $function$','s');EXECUTE d;END LOOP;END $$;
DO $$ DECLARE f record;d text; marker text:='PERFORM pg_advisory_xact_lock(60412026,6);'; BEGIN FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('record_receipt','allocate_receipt','verify_receipt','reverse_receipt','waive_installment','activate_contract','set_contract_state','update_draft_contract','save_payment_plan','refresh_installments','set_unit_status') LOOP SELECT pg_get_functiondef(f.oid) INTO d;IF position(marker IN d)=0 THEN d:=regexp_replace(d,'\mBEGIN\M','BEGIN '||marker,'i');EXECUTE d;END IF;END LOOP;END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.reverse_receipt(uuid,text)'::regprocedure) INTO d;IF position('مصدر الإيصال التاريخي' IN d)=0 THEN d:=replace(d,'INSERT INTO public.receipts(id,party_id,contract_id,booking_id,paid_at,method','IF r.archived_at IS NOT NULL OR EXISTS(SELECT 1 FROM public.receipt_legacy_sources WHERE receipt_id=r.id AND resolution<>''distinct'') THEN RAISE EXCEPTION ''راجع مصدر الإيصال التاريخي قبل العكس'';END IF; INSERT INTO public.receipts(id,party_id,contract_id,booking_id,paid_at,method');EXECUTE d;END IF;SELECT pg_get_functiondef('public.waive_installment(uuid,text)'::regprocedure) INTO d;d:=replace(d,'EXISTS(SELECT 1 FROM public.receipt_allocations WHERE installment_id=i.id)','EXISTS(SELECT 1 FROM public.receipt_allocations a JOIN public.receipts r ON r.id=a.receipt_id WHERE a.installment_id=i.id AND r.status IN (''recorded'',''verified'') AND r.reverses_id IS NULL AND r.archived_at IS NULL AND a.reverses_id IS NULL)');EXECUTE d;SELECT pg_get_functiondef('public.activate_contract(uuid,text)'::regprocedure) INTO d;IF position('عميل العقد مؤرشف' IN d)=0 THEN d:=replace(d,'SELECT * INTO p FROM public.payment_plans WHERE id=c.payment_plan_id;','PERFORM 1 FROM public.parties WHERE id=c.party_id AND archived_at IS NULL AND merged_into_id IS NULL FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION ''عميل العقد مؤرشف أو مدموج'';END IF; SELECT * INTO p FROM public.payment_plans WHERE id=c.payment_plan_id FOR UPDATE;');EXECUTE d;END IF;END $$;
SELECT tgrelid::regclass AS historical_table,tgname FROM pg_trigger WHERE tgname='finance_legacy_readonly';